//! Generation of `contracts/ts/` and `contracts/examples/`, and the comparison with disk.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use bansayo_contracts::*;
use ts_rs::{Config, TS, TypeVisitor};

use super::examples;

/// Set to `1` to rewrite the generated directories instead of failing when they are stale.
pub const BLESS_VAR: &str = "BANSAYO_BLESS";

const INDEX_HEADER: &str =
    "// This file was generated by bansayo-contracts. Do not edit this file manually.\n";

pub fn contracts_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../contracts")
}

/// TypeScript config: 64-bit integers are `number` (JSON numbers, safe up to 2^53).
fn ts_config() -> Config {
    Config::new().with_large_int("number")
}

struct Collect<'a> {
    cfg: &'a Config,
    files: BTreeMap<String, String>,
}

impl TypeVisitor for Collect<'_> {
    fn visit<T: TS + 'static + ?Sized>(&mut self) {
        let Some(path) = T::output_path() else { return };
        let name = path.to_string_lossy().replace('\\', "/");
        if self.files.contains_key(&name) {
            return;
        }
        let body =
            T::export_to_string(self.cfg).unwrap_or_else(|e| panic!("exporting {name}: {e}"));
        // ts-rs emits spaces before some line breaks; keep checked-in output whitespace-clean.
        let body = body
            .lines()
            .map(str::trim_end)
            .collect::<Vec<_>>()
            .join("\n")
            + "\n";
        self.files.insert(name, body);
        T::visit_dependencies(self);
    }
}

/// Every TypeScript file, keyed by file name: the root types and everything they reference.
pub fn typescript() -> BTreeMap<String, String> {
    let cfg = ts_config();
    let mut c = Collect {
        cfg: &cfg,
        files: BTreeMap::new(),
    };
    c.visit::<ServerMessage>();
    c.visit::<MotionSample>();
    c.visit::<SourceEvent>();
    c.visit::<CalibrationProfile>();
    c.visit::<MountingData>();
    c.visit::<MountingQuality>();
    c.visit::<CameraIntrinsicsData>();
    c.visit::<CameraExtrinsicsData>();
    c.visit::<RecordingSession>();
    c.visit::<ApiResponse<HealthResponse>>();
    c.visit::<HealthResponse>();
    c.visit::<DeletedResponse>();
    c.visit::<PlaybackStopResponse>();
    c.visit::<AssignmentRequest>();
    c.visit::<ReferencePoseRequest>();
    c.visit::<SimulationUpdateRequest>();
    c.visit::<FaultRequest>();
    c.visit::<RecordingStartRequest>();
    c.visit::<PlaybackStartRequest>();
    c.visit::<PlaybackUpdateRequest>();
    c.visit::<AthleteProfile>();
    c.visit::<CreateAthleteRequest>();
    c.visit::<ConsentRequest>();
    c.visit::<ActiveAthleteRequest>();
    c.visit::<CreateSessionRequest>();
    c.visit::<TrainingCommandRequest>();
    c.visit::<TrainingSessionSummary>();
    c.visit::<TrainingSessionDetail>();
    c.visit::<SessionProvenance>();
    c.visit::<RpeRequest>();
    c.visit::<ContentIndex>();
    c.visit::<SeriesResponse>();
    c.visit::<ProgressSummary>();
    c.visit::<RepTrace>();
    c.visit::<MotionClip>();
    c.visit::<ReanalyseRequest>();
    c.visit::<ReanalyseResponse>();
    let mut files = c.files;
    let index: String = files
        .keys()
        .map(|f| {
            let name = f.trim_end_matches(".ts");
            format!("export type {{ {name} }} from \"./{name}\";\n")
        })
        .collect();
    files.insert("index.ts".into(), format!("{INDEX_HEADER}\n{index}"));
    files
}

pub fn examples() -> BTreeMap<String, String> {
    examples::all()
        .into_iter()
        .map(|e| (e.file, e.text))
        .collect()
}

/// Differences between `expected` and the files in `dir`, as human-readable lines.
fn diff(dir: &Path, expected: &BTreeMap<String, String>) -> Vec<String> {
    let mut problems = vec![];
    let mut on_disk = BTreeMap::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            // Line endings are normalised so a CRLF checkout on Windows is not reported as stale.
            let text = fs::read_to_string(entry.path())
                .ok()
                .map(|t| t.replace("\r\n", "\n"));
            on_disk.insert(name, text);
        }
    }
    for (name, want) in expected {
        match on_disk.get(name) {
            None => problems.push(format!("missing: {}", dir.join(name).display())),
            Some(have) if have.as_deref() != Some(want.as_str()) => {
                problems.push(format!("stale: {}", dir.join(name).display()))
            }
            Some(_) => {}
        }
    }
    for name in on_disk.keys().filter(|n| !expected.contains_key(*n)) {
        problems.push(format!("unexpected: {}", dir.join(name).display()));
    }
    problems
}

fn write(dir: &Path, expected: &BTreeMap<String, String>) {
    fs::create_dir_all(dir).expect("create output directory");
    for entry in fs::read_dir(dir).expect("read output directory").flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        if !expected.contains_key(&name) {
            let path = entry.path();
            let removed = if path.is_dir() {
                fs::remove_dir_all(&path)
            } else {
                fs::remove_file(&path)
            };
            removed.expect("remove unexpected file");
        }
    }
    for (name, text) in expected {
        let path = dir.join(name);
        if fs::read_to_string(&path).ok().as_deref() != Some(text.as_str()) {
            fs::write(&path, text).expect("write generated file");
        }
    }
}

pub fn blessing() -> bool {
    std::env::var(BLESS_VAR).as_deref() == Ok("1")
}

/// Fails listing every stale, missing or unexpected file, or rewrites them when blessing.
pub fn check_or_bless() {
    let root = contracts_dir();
    let sets = [
        (root.join("ts"), typescript()),
        (root.join("examples"), examples()),
    ];
    if blessing() {
        for (dir, files) in &sets {
            write(dir, files);
        }
        return;
    }
    let problems: Vec<String> = sets
        .iter()
        .flat_map(|(dir, files)| diff(dir, files))
        .collect();
    assert!(
        problems.is_empty(),
        "generated contracts are out of date; run `{BLESS_VAR}=1 cargo test -p bansayo-contracts` \
         and review the diff:\n  {}",
        problems.join("\n  ")
    );
}
